import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec3, mix, positionLocal, normalLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Texture, Color } = THREE;

  const root = new Group();
  root.name = 'features-list-row';
  root.userData.handlers = {};

  const resources = [];
  const timelines = [];
  let disposed = false;

  const backdropGeometry = new PlaneGeometry(7, 6, 1, 1);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropUv = uv();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.91, 0.925, 0.949),
      backdropUv.y.mul(0.18)
    ),
    backdropUv.y
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const imageTexture = new Texture();
  const depthTexture = new Texture();
  resources.push(imageTexture, depthTexture);

  const rowGeometry = new PlaneGeometry(5.6, 1.15, 64, 64);
  const rowMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1
  });

  rowMaterial.colorNode = texture(imageTexture);
  rowMaterial.positionNode = positionLocal;

  const row = new Mesh(rowGeometry, rowMaterial);
  row.name = 'features-parallax-row';
  row.position.set(0, 0, 0);
  root.add(row);
  resources.push(rowGeometry, rowMaterial);

  const dividerGeometry = new PlaneGeometry(5.25, 0.012, 1, 1);
  const dividerMaterial = new MeshBasicNodeMaterial({
    color: new Color('#e8ecf2'),
    transparent: true,
    opacity: 0.28
  });
  const divider = new Mesh(dividerGeometry, dividerMaterial);
  divider.name = 'subtle-divider';
  divider.position.set(0, -0.48, 0.08);
  root.add(divider);
  resources.push(dividerGeometry, dividerMaterial);

  const edgeGeometry = new PlaneGeometry(0.035, 0.94, 1, 1);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: new Color('#ff2a38'),
    transparent: true,
    opacity: 0
  });
  const edge = new Mesh(edgeGeometry, edgeMaterial);
  edge.name = 'focus-accent-edge';
  edge.position.set(2.76, 0, 0.1);
  root.add(edge);
  resources.push(edgeGeometry, edgeMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const role = item.role ?? 'body';
    const fontSize =
      item.typography?.fontSize ??
      (role === 'hero' ? 68 : role === 'headline' ? 40 : role === 'caption' ? 18 : 24);

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: role === 'caption' ? '#ff2a38' : '#e8ecf2',
      align: role === 'caption' ? 'right' : 'left',
      maxWidthPx: 900,
      letterSpacingPx: role === 'caption' ? Math.round(fontSize * 0.08) : 0
    });

    textObject.position.set(-2.42, role === 'caption' ? 0.28 : -0.04, 0.12);
    root.add(textObject);
  }

  const entrance = gsap.timeline({ paused: true });
  entrance.fromTo(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  entrance.fromTo(
    row.position,
    { y: -0.15 },
    { y: 0, duration: 0.7, ease: 'power3.out' },
    0
  );
  timelines.push(entrance);
  entrance.play();

  const hoverLift = gsap.timeline({ paused: true });
  hoverLift.to(row.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power3.out'
  });
  timelines.push(hoverLift);

  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline.to(row.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'power2.out'
  });
  pressTimeline.to(row.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.28,
    ease: 'back.out(2)'
  });
  timelines.push(pressTimeline);

  const parallaxTimeline = gsap.timeline({ paused: true });
  timelines.push(parallaxTimeline);

  root.userData.handlers.hover = (active = true) => {
    if (disposed) return;
    if (active) hoverLift.play();
    else hoverLift.reverse();
  };

  root.userData.handlers.pointermove = (event = {}) => {
    if (disposed) return;

    const nx = Math.max(-1, Math.min(1, Number(event.x ?? event.normalizedX ?? 0)));
    const ny = Math.max(-1, Math.min(1, Number(event.y ?? event.normalizedY ?? 0)));

    parallaxTimeline.kill();
    parallaxTimeline.clear();
    parallaxTimeline
      .to(row.rotation, {
        x: -ny * 0.035,
        y: nx * 0.05,
        duration: 0.32,
        ease: 'power2.out'
      })
      .to(row.position, {
        x: nx * 0.045,
        y: ny * 0.035 + (hoverLift.isActive() ? 0.15 : 0),
        duration: 0.32,
        ease: 'power2.out'
      }, 0)
      .play();
  };

  root.userData.handlers.focus = (focused = true) => {
    if (disposed) return;

    gsap.to(edgeMaterial, {
      opacity: focused ? 0.95 : 0,
      duration: 0.22,
      ease: 'power2.out'
    });
  };

  root.userData.handlers.click = () => {
    if (disposed) return;

    pressTimeline.restart();
    ctx.emit('hub-features.select', {
      node: 'hub-features',
      checkoutUrl: config.dataBindings?.['trpc.checkout.begin.checkoutUrl'] ?? null
    });
  };

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((loadedTexture) => {
      if (disposed || !loadedTexture) return;
      rowMaterial.colorNode = texture(loadedTexture);
      rowMaterial.needsUpdate = true;
      resources.push(loadedTexture);
    }).catch(() => {});
  }

  if (config.depthMapUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((loadedDepth) => {
      if (disposed || !loadedDepth) return;

      const depthNode = texture(loadedDepth).r;
      rowMaterial.positionNode = positionLocal.add(
        normalLocal.mul(depthNode.mul(0.12))
      );
      rowMaterial.needsUpdate = true;
      resources.push(loadedDepth);
    }).catch(() => {});
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }
    gsap.killTweensOf(root);
    gsap.killTweensOf(row);
    gsap.killTweensOf(row.position);
    gsap.killTweensOf(row.rotation);
    gsap.killTweensOf(edgeMaterial);

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        for (const material of materials) {
          if (material.dispose) material.dispose();
        }
      }
    });

    for (const resource of resources) {
      if (resource?.dispose) resource.dispose();
    }
  };

  return root;
}
